func (s *Server) handleListProducts(w http.ResponseWriter, r *http.Request) {
	// Read the query parameter in the path
	inStock := r.URL.Query().Get("in_stock")
	var filteredProducts []Product
	var err error

	if inStock == "" {
		// No filter: return all products sorted by ID
		filteredProducts = s.products.List()
	} else {
		// Parse the boolean value of the query parameter
		var shouldInclude int
		if _, err := strconv.Atoi(inStock); err == nil {
