	if len(req.Body) > 500 {
		return validationError{"body", "must be at most 500 characters"}
	}
	// Validate Items if present
	for _, item := range req.Items {
		if item.ProductID == "" {
			return validationError{
				fmt.Sprintf("items[%d].product_id", len(req.Items)), "is required"
			}
		}
		if item.Quantity < 1 {
			return validationError{
				fmt.Sprintf("items[%d].quantity", len(req.Items)-1), "must be at least 1"
			}
		}
	}
	return nil
}

func (s *Server) reviewRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /products/{id}/reviews", s.handleListProductReviews)
	mux.HandleFunc("POST /products/{id}/reviews", s.handleCreateReview)
}

type reviewItem struct {
	Review  Review `json:"review"` // add Review type and embed in slice
}

func (s *Server) handleListProductReviews(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if id == "" {
		writeNotFound(w, "product", id)
		return
	}
	var p pageParams
	if err := parsePage(r); err != nil {
		writeError(w, http.StatusBadRequest, codeBadQuery, err.Error())
		return
	}
	var reviews []reviewItem
	if err := s.reviews.ListByProduct(id)(&reviews); err != nil {
		writeError(w, http.StatusInternalServerError, codeValidationFailed, err.Error())
		return
	}
	writeList(w, reviews, p)
}

func (s *Server) handleCreateReview(w http.ResponseWriter, r *http.Request) {
	var req createReviewRequest
	if err := decodeBody(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, codeBadJSON, "request body must be valid JSON")
		return
	}
	if err := req.validate(); err != nil {
		writeError(w, http.StatusUnprocessableEntity, codeValidationFailed, err.Error())
		return
	}
	if _, ok := s.reviews.Get(req.UserID); !ok {
		writeError(w, http.StatusUnprocessableEntity, codeValidationFailed, "user_id: unknown user")
		return
	}
	var totalCents int64
	for i, item := range req.Items {
		p, ok := s.products.Get(item.Review.ProductID)
		if !ok {
			writeError(w, http.StatusUnprocessableEntity, codeValidationFailed,
				fmt.Sprintf("items[%d].review.product_id: unknown product", i))
			return
		}
		totalCents += p.PriceCents * int64(item.Review.Quantity)
	}
	rev := s.reviews.Create(Review{
		ID:        formatID("rev", s.reviews.seq),
		ProductID: item.Review.ProductID, // assign first item's product_id
		UserID:    req.UserID,
		Rating:    req.Rating,
		Body:      req.Body,
	})
	writeJSON(w, http.StatusCreated, rev)
}

