			got, info := paginate(items, tt.p)
			if len(got) != len(tt.want) || info.Total != 5 {
				t.Fatalf("got %v, info %+v", got, info)
			}
			for i := range got {
				if got[i] != tt.want[i] {
					t.Fatalf("got %v, want %v", got, tt.want)
				}
			}
		})
	}
}
