	store := NewReviewStore()
	rv := Review{
		ID:        "rev_000001",
		ProductID: "prod_1",
		UserID:    "",
		Rating:    4,
		Body:      "",
	}
	store.items[rv.ID] = rv

	got, ok := store.Get("rev_000001")
	if ok != true {
		t.Errorf("Get = ok = %v, want %v", ok, true)
	}
	if got != rv {
		t.Errorf("got = %v, want %v", got, rv)
	}

	_, ok = store.Get("nonexistent")
	if ok != false {
		t.Errorf("Get = ok = %v, want %v", ok, false)
	}
