	if strings.TrimSpace(req.Name) == "" {
		return validationError{"name", "is required"}
	}
	if req.PriceCents <= 0 {
		return validationError{"price_cents", "must be greater than 0"}
	}
	if req.Stock < 0 {
		return validationError{"stock", "must not be negative"}
	}
	return nil
}

func (s *Server) handleListProducts(w http.ResponseWriter, r *http.Request) {
	// Parse query parameter for in_stock
	inStock := false
	if val := r.URL.Query().Get("in_stock"); val != "" {
		switch val {
		case "true":
			inStock = true
		case "false":
			inStock = false
		default:
			writeError(w, http.StatusBadRequest, codeBadQuery, "in_stock must be true or false")
			return
		}
	}

	var filtered []Product
	if inStock {
		for _, p := range s.products.List() {
			if p.Stock > 0 {
				filtered = append(filtered, p)
			}
		}
	} else {
		for _, p := range s.products.List() {
			if p.Stock == 0 {
				filtered = append(filtered, p)
			}
		}
	}

	// Ensure sorted order
	slices.SortFunc(filtered, func(a, b Product) int { return strings.Compare(a.ID, b.ID) })

	writeJSON(w, http.StatusOK, filtered)
}

