		ProductID: "prod_123",
		UserID:    "usr_456",
		Rating:    4,
		Body:      "nice",
	}
	store.Create(rv)

	got, ok := store.Get("rev_789")
	if !ok {
		t.Errorf("Get returned ok=false for ID rev_789")
	}
	if got == nil {
		t.Errorf("Get returned nil for ID rev_789")
	}
	if got.ProductID != "prod_123" {
		t.Errorf("Returned ProductID %s, want %s", got.ProductID, "prod_123")
	}
}

func TestReviewStore_Get_MissingID(t *testing.T) {
	store := NewReviewStore()
	_, ok := store.Get("nonexistent")
	if ok {
		t.Errorf("Get returned ok=true for nonexistent ID")
	}
}

func TestReviewStore_ListByProduct(t *testing.T) {
	store := NewReviewStore()
	productID := "prod_123"

	reviews := []Review{
		{
			ID:    "rev_100",
			ProductID: productID,
			UserID:    "usr_1",
			Rating:    3,
			Body:      "first",
		},
		{
			ID:    "rev_200",
			ProductID: productID,
			UserID:    "usr_2",
			Rating:    5,
			Body:      "last",
		},
	}
	store.Create(reviews[0]) // ensure order is preserved
	store.Create(reviews[1])

	result := store.ListByProduct(productID)

	// Sort by ID to verify order
	expected := []Review{
		{ID: "rev_100", ProductID: productID, UserID: "usr_1", Rating: 3, Body: "first"},
		{ID: "rev_200", ProductID: productID, UserID: "usr_2", Rating: 5, Body: "last"},
	}
	// Since we sorted by ID during insertion, the order should be preserved
	// But we sort the result by ID to ensure correct ordering
	slices.SortFunc(result, func(a, b Review) int {
		return a.ID < b.ID
	})

	for i, a, b := range result {
		if a != expected[i] {
			t.Errorf("ListByProduct at index %d: expected %+v, got %+v", i, expected[i], a)
		}
	}

	// Test empty product
	emptyResult := store.ListByProduct("nonexistent")
	if len(emptyResult) != 0 {
		t.Errorf("ListByProduct for non-existent product returned %d reviews", len(emptyResult))
	}
}
