        """Returns all users sorted by ID."""
        with self._lock:
            return [dataclasses.replace(u) for u in sorted(self._items.values(), key=lambda u: u.id)]

    def delete(self, id):
        """Reports whether the user existed."""
        with self._lock:
            return self._items.pop(id, None) is not None
